 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function entry(food){const key=root.IngredientIdentity?.key(food)||food.id;return (foods[key]||[]).map(id=>taxa[id]);}
 function html(food){
  const entries=entry(food);if(!entries.length)return '';
  return entries.map(t=>{
  const lineage=t.ranks.map((value,i)=>`<li><strong>${labels[i]}</strong> · ${value?`${chinese[value]?esc(chinese[value])+' · ':''}<i>${esc(value)}</i>`:i===6?'种暂未核实':'暂未核实'}</li>`).join('');
  const citation=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
  return `<p><strong>${esc(t.name)}</strong> · <i>${esc(t.latin)}</i></p>${t.synonyms?.length?`<p>常见异名 · ${t.synonyms.map(n=>`<i>${esc(n)}</i>`).join('、')}</p>`:''}${t.domain?`<p>域 · ${esc(t.domain)}</p>`:''}<ol class="biology-lineage">${lineage}</ol>${t.note?`<p>${esc(t.note)}</p>`:''}${t.native?`<p>原生分布 · ${esc(t.native)}</p>`:''}${t.cultivar?`<p>地方品种 · ${esc(t.cultivar)}</p>`:''}<p>早期人工培育 · ${esc(t.origin||'资料正在核实')}</p>${t.originSources?.length?`<p>${t.originSources.map(([url,label])=>citation(url,label)).join(' · ')}</p>`:''}<p>分类依据 · Catalogue of Life Base 2026-10-14，检索于 ${esc(t.checked||'2026-11-11')} · ${citation(col+t.id,'查看分类记录')} · ${citation(t.source,'查看食材与物种资料')}</p>`;
  }).join('');
 }
